// LRU Cache: hash map (key -> node) + doubly linked list (recency order)
class Node {
  constructor(key, val) {
    this.key = key; this.val = val;
    this.prev = null; this.next = null;
  }
}

class LRUCache {
  constructor(capacity) {
    this.capacity = capacity;
    this.map = new Map();          // key -> Node, O(1) lookup
    this.head = new Node(0, 0);    // dummy head = most recently used side
    this.tail = new Node(0, 0);    // dummy tail = least recently used side
    this.head.next = this.tail;
    this.tail.prev = this.head;
  }

  _remove(node) {
    node.prev.next = node.next;
    node.next.prev = node.prev;
  }

  _insertAtFront(node) {
    node.next = this.head.next;
    node.prev = this.head;
    this.head.next.prev = node;
    this.head.next = node;
  }

  get(key) {
    if (!this.map.has(key)) return -1;
    const node = this.map.get(key);
    this._remove(node);
    this._insertAtFront(node);      // touched -> becomes most recently used
    return node.val;
  }

  put(key, value) {
    if (this.map.has(key)) this._remove(this.map.get(key));
    const node = new Node(key, value);
    this.map.set(key, node);
    this._insertAtFront(node);
    if (this.map.size > this.capacity) {
      const lru = this.tail.prev;   // least recently used = right before dummy tail
      this._remove(lru);
      this.map.delete(lru.key);
    }
  }
}
